package com.csust.eyediagnosis.workflow.evidence;
import org.junit.jupiter.api.Test; import java.util.concurrent.atomic.AtomicInteger; import static org.junit.jupiter.api.Assertions.*;
class RetrievalSourceValidationActionTest { @Test void delegatesWithoutRetrievingOrRewriting() { AtomicInteger calls = new AtomicInteger(); RetrievalSourceValidationAction action = new RetrievalSourceValidationAction((intent, batch) -> { calls.incrementAndGet(); return new DefaultRetrievalSourceValidator(new FixedEvidenceTermCatalog()).validate(intent, batch); }); assertTrue(action.execute(EvidenceFixtures.intent(), new EvidenceRetrievalBatch(EvidenceFixtures.intent(), EvidenceFixtures.query(), java.util.List.of(EvidenceFixtures.candidate()), false)).sufficiency().sufficient()); assertEquals(1, calls.get()); } }
